#include <stdio.h>

int main() {
    int a, n, m, x;
    scanf("%d %d %d %d", &a, &n, &m, &x);

    /* 预处理各车站的系数数组 */
    // up_a[k]: 第k站上车人数中a的系数（斐波那契规律）
    // up_u[k]: 第k站上车人数中u的系数（斐波那契规律）
    // A[k]: 第k站总人数中a的系数，B[k]: 第k站总人数中u的系数
    int up_a[21] = {0}, up_u[21] = {0}; // 下标1~20对应车站1~20
    int A[21] = {0}, B[21] = {0};

    /* 初始化前两站上车系数 */
    up_a[1] = 1; // 第1站上车全为a: a*1 + u*0
    up_u[1] = 0;
    up_a[2] = 0; // 第2站上车全为u: a*0 + u*1 
    up_u[2] = 1;

    /* 递推计算3~20站的上车系数（斐波那契规律） */
    // 从第3站起，上车人数=前两站上车人数之和
    // 例：第3站上车系数 = 第2站系数 + 第1站系数
    for (int k = 3; k <= 20; k++) {
        up_a[k] = up_a[k-1] + up_a[k-2];
        up_u[k] = up_u[k-1] + up_u[k-2];
    }

    /* 初始化前两站总人数系数 */
    A[1] = 1; // 第1站总人数 = 1*a + 0*u
    B[1] = 0;
    A[2] = 1; // 第2站上下车抵消，总人数仍为a
    B[2] = 0;

    /* 递推计算3~20站的总人数系数 */
    // 总人数变化 = 当前站上车人数 - 前一站上车人数（因为下车人数=前一站上车人数）
    for (int k = 3; k <= 20; k++) {
        // 计算a和u的系数变化量
        int delta_a = up_a[k] - up_a[k-1]; // 上车a系数 - 下车a系数（前一站的上车a系数）
        int delta_u = up_u[k] - up_u[k-1]; // 上车u系数 - 下车u系数（前一站的上车u系数）
        // 累加得到当前总系数
        A[k] = A[k-1] + delta_a;
        B[k] = B[k-1] + delta_u;
    }

    /* 处理特殊车站数情况 */
    if (n == 1 || n == 2) {
        // 只有1个站：直接输出a
        // 2个站时，第2站开出时人数仍为a
        printf("%d\n", a);
    } else {
        /* 通过终点站的下车人数m求解u */
        int k = n - 1; // 终点站前最后一站是第n-1站
        int A_val = A[k]; // 总人数a的系数
        int B_val = B[k]; // 总人数u的系数

        if (B_val == 0) {
            // 如果u的系数为0，说明总人数与u无关，直接计算
            printf("%d\n", A[x] * a);
        } else {
            // 解方程：A_val * a + B_val * u = m
            // 这里m是第n站的下车人数，等于第n-1站的总人数
            int u = (m - A_val * a) / B_val;
            // 计算第x站的总人数：A[x]*a + B[x]*u
            printf("%d\n", A[x] * a + B[x] * u);
        }
    }

    return 0;
}

/* 代码逻辑总结：
   1. 预处理各站点的上车人数系数(up_a/up_u)和总人数系数(A/B)
   2. 利用最后一站的下车人数m建立方程，反推第2站的未知数u
   3. 将a和u代入目标站点x的系数公式，得到最终人数
*/
/*# [NOIP1998 提高组] 车站
## 题目描述
火车从始发站（称为第 $1$ 站）开出，在始发站上车的人数为 $a$，然后到达第 $2$ 站，在第 $2$ 站有人上、下车，但上、下车的人数相同，
因此在第 $2$ 站开出时（即在到达第 $3$ 站之前）车上的人数保持为 $a$ 人。从第 $3$ 站起（包括第 $3$ 站）上、下车的人数有一定规律：
上车的人数都是前两站上车人数之和，而下车人数等于上一站上车人数，一直到终点站的前一站（第 $n-1$ 站），都满足此规律。
现给出的条件是：共有 $n$ 个车站，始发站上车的人数为 $a$，最后一站下车的人数是 $m$（全部下车）。试问 $x$ 站开出时车上的人数是多少？
## 输入格式
输入只有一行四个整数，分别表示始发站上车人数 $a$，车站数 $n$，终点站下车人数 $m$ 和所求的站点编号 $x$。
## 输出格式
输出一行一个整数表示答案：从 $x$ 站开出时车上的人数。
## 样例 #1
### 样例输入 #1
```
5 7 32 4
```
### 样例输出 #1
```
13
```
## 提示
对于全部的测试点，保证 $1 \leq a \leq 20$，$1 \leq x \leq n \leq 20$，$1 \leq m \leq 2 \times 10^4$。
*/